//
// Extinguish source share debt and move the same backing stake to a same-validator destination.
// Callable only by ValidatorShare. When both token IDs match, only debt is reduced.
type IDiesisPositionRedeemShareBackingParams struct {
	FromTokenId *big.Int
	ToTokenId   *big.Int
	ShareAmount *big.Int
}

// IDiesisPositionRepayLiquidTokenParams holds the arguments of repayLiquidToken(uint256,uint256).
type IDiesisPositionRepayLiquidTokenParams struct {
	TokenId    *big.Int
	BurnAmount *big.Int
}

// IDiesisPositionRestakeRewardsParams holds the arguments of restakeRewards(uint256).
type IDiesisPositionRestakeRewardsParams struct {
	TokenId *big.Int
}

// IDiesisPositionRevokeFunctionApprovalParams holds the arguments of revokeFunctionApproval(uint256,uint8).
type IDiesisPositionRevokeFunctionApprovalParams struct {
	TokenId *big.Int
	Fn      uint8
}

// IDiesisPositionSafeTransferFromParams holds the arguments of safeTransferFrom(address,address,uint256).
//
// Safely transfers `tokenId` token from `from` to `to`, checking first that contract recipients are aware of the ERC-721 protocol to prevent tokens from being forever locked. Requirements: - `from` cannot be the zero address. - `to` cannot be the zero address. - `tokenId` token must exist and be owned by `from`. - If the caller is not `from`, it must have been allowed to move this token by either {approve} or {setApprovalForAll}. - If `to` refers to a smart contract, it must implement {IERC721Receiver-onERC721Received}, which is called upon a safe transfer. Emits a {Transfer} event.
type IDiesisPositionSafeTransferFromParams struct {
	From    common.Address
	To      common.Address
	TokenId *big.Int
}

// IDiesisPositionSafeTransferFrom0Params holds the arguments of safeTransferFrom(address,address,uint256,bytes).
//
// Safely transfers `tokenId` token from `from` to `to`. Requirements: - `from` cannot be the zero address. - `to` cannot be the zero address. - `tokenId` token must exist and be owned by `from`. - If the caller is not `from`, it must be approved to move this token by either {approve} or {setApprovalForAll}. - If `to` refers to a smart contract, it must implement {IERC721Receiver-onERC721Received}, which is called upon a safe transfer. Emits a {Transfer} event.
type IDiesisPositionSafeTransferFrom0Params struct {
	From    common.Address
	To      common.Address
	TokenId *big.Int
	Data    []byte
}

// IDiesisPositionSetApprovalForAllParams holds the arguments of setApprovalForAll(address,bool).
//
// Approve or remove `operator` as an operator for the caller. Operators can call {transferFrom} or {safeTransferFrom} for any token owned by the caller. Requirements: - The `operator` cannot be the address zero. Emits an {ApprovalForAll} event.
type IDiesisPositionSetApprovalForAllParams struct {
	Operator common.Address
	Approved bool
}

// IDiesisPositionSetFunctionApprovalParams holds the arguments of setFunctionApproval(uint256,uint8,address,uint32,bool).
type IDiesisPositionSetFunctionApprovalParams struct {
	TokenId   *big.Int
	Fn        uint8
	Delegatee common.Address
	Expires   uint32
	Revokable bool
}

// IDiesisPositionShareDebtOfParams holds the arguments of shareDebtOf(uint256).
//
// Return the share debt for a position.
type IDiesisPositionShareDebtOfParams struct {
	TokenId *big.Int
}

