type IDiesisPositionSwapDelegateParams struct {
	FromTokenId *big.Int
	ToTokenId   *big.Int
	SwapAmount  *big.Int
}

// IDiesisPositionTotalDebtOfParams holds the arguments of totalDebtOf(uint256).
